// The arcade's side of the chain: read blocks, and sign + submit submit_score with the arcade key.
// The key never leaves this process; players never see or hold one.
import fs from 'node:fs';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { bls12_381 } from '@noble/curves/bls12-381.js';

const require = createRequire(import.meta.url);
// generated by the plugin build, so the server and the plugin encode identically
const protoRoot = require(process.env.BARRAGE_PROTO || '../plugin/dist/proto/index.cjs');
const { types, google } = protoRoot;

export class Chain {
  constructor({ rpc, pluginRpc, chainId, networkId = 1, fee = 10_000n, keyFile }) {
    this.rpc = rpc.replace(/\/$/, '');
    this.pluginRpc = pluginRpc.replace(/\/$/, '');
    this.chainId = BigInt(chainId);
    this.networkId = BigInt(networkId);
    this.fee = BigInt(fee);
    this.key = null;
    if (keyFile && fs.existsSync(keyFile)) {
      const k = JSON.parse(fs.readFileSync(keyFile, 'utf8'));
      if (!/^[0-9a-f]{40}$/.test(k.address) || !k.privateKey || !k.publicKey) throw new Error(`bad key file ${keyFile}`);
      this.key = k;
    }
  }

  async post(path, body, base = this.rpc, timeout = 2000) {
    const r = await fetch(`${base}${path}`, {
      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body), signal: AbortSignal.timeout(timeout),
    });
    const text = await r.text();
    if (!r.ok) throw new Error(`${path} ${r.status}: ${text.slice(0, 300)}`);
    return text ? JSON.parse(text) : null;
  }

  async getPlugin(path, timeout = 2000) {
    const r = await fetch(`${this.pluginRpc}${path}`, { signal: AbortSignal.timeout(timeout) });
    const body = await r.json();
    if (!r.ok) throw new Error(`${path} ${r.status}: ${JSON.stringify(body)}`);
    return body;
  }

  /** the height the node will build next; the newest committed block is one below it */
  async nextHeight() {
    const h = Number((await this.post('/v1/query/height', {})).height);
    if (!Number.isSafeInteger(h)) throw new Error('bad height');
    return h;
  }

  async block(height) {
    const b = await this.post('/v1/query/block-by-height', { height });
    const hd = b?.blockHeader || b?.block_header || {};
    return {
      h: Number(hd.height ?? height),
      hash: String(hd.hash || '').toLowerCase(),
      t: Math.floor(Number(hd.time || 0) / 1000), // µs -> ms
      txs: Number(hd.numTxs ?? hd.num_txs ?? 0),
      proposer: String(hd.proposerAddress || hd.proposer_address || '').slice(0, 8),
    };
  }

  /** build, sign and broadcast submit_score; returns the tx hash */
  async submitScore(f) {
    if (!this.key) throw new Error('no arcade key: run npm run keygen');
    const fields = {
      address: Buffer.from(this.key.address, 'hex'), runId: Buffer.from(f.runId, 'hex'), initials: f.initials,
      score: f.score, startHeight: f.startHeight, endHeight: f.endHeight, kills: f.kills,
      bestMultiplier: f.bestMultiplier, powerLevel: f.powerLevel,
    };
    const msgType = 'submit_score';
    const typeUrl = 'type.googleapis.com/types.MessageSubmitScore';
    const proto = omitDefaults(fields);
    const msgBytes = types.MessageSubmitScore.encode(types.MessageSubmitScore.create(proto)).finish();
    const msgJSON = {};
    for (const [k, v] of Object.entries(proto)) msgJSON[k] = Buffer.isBuffer(v) ? v.toString('hex') : v;
    const created = await this.nextHeight();
    const time = BigInt(Date.now()) * 1000n;
    const unsigned = types.Transaction.create(omitDefaults({
      messageType: msgType, msg: google.protobuf.Any.create({ type_url: typeUrl, value: msgBytes }),
      createdHeight: created, time: Number(time), fee: Number(this.fee), networkId: Number(this.networkId), chainId: Number(this.chainId),
    }));
    const signBytes = types.Transaction.encode(unsigned).finish();
    const sig = bls12_381.longSignatures.sign(bls12_381.longSignatures.hash(signBytes), Buffer.from(this.key.privateKey, 'hex'));
    const tx = {
      type: msgType, msg: msgJSON,
      signature: { publicKey: this.key.publicKey, signature: Buffer.from(bls12_381.longSignatures.Signature.toBytes(sig)).toString('hex') },
      time: Number(time), createdHeight: created, fee: Number(this.fee), memo: '',
      networkID: Number(this.networkId), chainID: Number(this.chainId),
    };
    return this.post('/v1/tx', tx, this.rpc, 5000);
  }

  /** a tx's committed height, or null while pending; throws if the node reports it failed */
  async txStatus(hash, nextHeight) {
    try {
      const tx = await this.post('/v1/query/tx-by-hash', { hash });
      // tx-by-hash also returns mempool txs stamped with the next height: committed only once below it
      if (tx?.height && Number(tx.height) < nextHeight) return { height: Number(tx.height) };
    } catch { /* not indexed yet */ }
    const failed = await this.post('/v1/query/failed-txs', { address: this.key.address, perPage: 50 });
    const hit = (failed?.results || []).find((x) => x.txHash === hash || x.transaction?.txHash === hash);
    if (hit) throw new Error(hit.error?.msg || JSON.stringify(hit.error));
    return null;
  }
}

// protobufjs encodes explicitly-set zeros but Go omits them; one extra field changes the signed bytes
function omitDefaults(fields) {
  const out = {};
  for (const [k, v] of Object.entries(fields)) {
    if (v === 0 || v === 0n || v === '' || v === false || v === null || v === undefined) continue;
    if ((v instanceof Uint8Array || Array.isArray(v)) && v.length === 0) continue;
    out[k] = v;
  }
  return out;
}

/** a fresh BLS key; address = sha256(compressed pubkey)[:20] (canopy lib/crypto/bls.go) */
export function newKey() {
  const priv = bls12_381.utils.randomSecretKey();
  const pub = bls12_381.longSignatures.getPublicKey(priv).toBytes(true);
  return {
    address: createHash('sha256').update(pub).digest().subarray(0, 20).toString('hex'),
    publicKey: Buffer.from(pub).toString('hex'),
    privateKey: Buffer.from(priv).toString('hex'),
  };
}
